<?php

declare(strict_types=1);

namespace App\Models;

use App\Enums\PaymentStatus;
use App\Support\Ids\HasPrefixedId;
use App\Support\Money\Money;
use Illuminate\Database\Eloquent\Model;
use Illuminate\Database\Eloquent\Relations\BelongsTo;
use Illuminate\Database\Eloquent\Relations\HasMany;
use Illuminate\Database\Eloquent\Relations\MorphTo;
use Illuminate\Support\Carbon;

/**
 * A single gateway charge attempt against a payable (order or listing promotion).
 * Status only ever changes after server-side verification with the gateway.
 */
/* @properties-start (generated by dev:model-docs) */
/**
 * @property string $id
 * @property string $reference
 * @property string $payable_type
 * @property string $payable_id
 * @property string $user_id
 * @property string $gateway
 * @property string|null $gateway_reference
 * @property int $amount
 * @property string $currency
 * @property int $refunded_amount
 * @property int|null $gateway_fee_amount
 * @property PaymentStatus $status
 * @property string|null $authorization_url
 * @property string|null $return_url
 * @property string|null $method_label
 * @property string|null $failure_reason
 * @property array|null $gateway_metadata
 * @property Carbon|null $verified_at
 * @property Carbon|null $expires_at
 * @property Carbon|null $created_at
 * @property Carbon|null $updated_at
 */
/* @properties-end */
class Payment extends Model
{
    use HasPrefixedId;

    protected static string $idPrefix = 'pay';

    protected $fillable = [
        'reference', 'payable_type', 'payable_id', 'user_id', 'gateway', 'gateway_reference', 'amount', 'currency',
        'status', 'authorization_url', 'return_url', 'method_label', 'failure_reason', 'gateway_metadata',
        'expires_at',
    ];

    protected $hidden = ['gateway_metadata'];

    protected $attributes = ['status' => 'pending'];

    protected function casts(): array
    {
        return [
            'status' => PaymentStatus::class,
            'amount' => 'integer',
            'refunded_amount' => 'integer',
            'gateway_fee_amount' => 'integer',
            'gateway_metadata' => 'array',
            'verified_at' => 'datetime',
            'expires_at' => 'datetime',
        ];
    }

    /** @return MorphTo<Model, $this> */
    public function payable(): MorphTo
    {
        return $this->morphTo();
    }

    /** @return BelongsTo<User, $this> */
    public function user(): BelongsTo
    {
        return $this->belongsTo(User::class);
    }

    /** @return HasMany<Refund, $this> */
    public function refunds(): HasMany
    {
        return $this->hasMany(Refund::class);
    }

    public function money(): Money
    {
        return Money::of($this->amount, $this->currency);
    }

    public function refundableAmount(): int
    {
        return $this->amount - $this->refunded_amount;
    }
}
